import{_ as e,o,c as d,a2 as a}from"./chunks/framework.CqGPl1zp.js";const c="/newx-doc/assets/%E7%BD%91%E5%85%B3%E4%B8%8E%E5%AD%90%E8%AE%BE%E5%A4%87%E6%9E%B6%E6%9E%84%E5%9B%BE.D0k3AWma.png",r="/newx-doc/assets/%E4%BA%A7%E5%93%81%E8%AE%BE%E5%A4%87%E7%B1%BB%E5%9E%8B.CmHduT2_.png",i="/newx-doc/assets/%E8%AE%BE%E5%A4%87%E8%AF%A6%E6%83%85-%E5%AD%90%E8%AE%BE%E5%A4%87%E7%AE%A1%E7%90%86.BbxD0COR.png",s="/newx-doc/assets/%E7%BB%91%E5%AE%9A%E5%AD%90%E8%AE%BE%E5%A4%87.Bhm6jPsq.png",v=JSON.parse('{"title":"设备网关与子设备","description":"","frontmatter":{},"headers":[],"relativePath":"iot/gateway-sub-device.md","filePath":"iot/gateway-sub-device.md","lastUpdated":null}'),n={name:"iot/gateway-sub-device.md"};function p(h,t,l,u,g,b){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="设备网关与子设备" tabindex="-1">设备网关与子设备 <a class="header-anchor" href="#设备网关与子设备" aria-label="Permalink to &quot;设备网关与子设备&quot;">​</a></h1><p>推荐阅读：</p><ul><li><a href="https://help.aliyun.com/zh/iot/user-guide/gateways-and-sub-devices" target="_blank" rel="noreferrer">《阿里云物联网平台 —— 网关与子设备》</a></li></ul><p>物联网平台支持设备直连，也支持设备挂载在网关上，作为网关的子设备，由网关直连。</p><p>使用场景：适用于子设备不能直连或者需要拓扑关系管理的场景，例如接入 Wi-Fi 网关、蓝牙网关、ZigBee 网关等。</p><blockquote><p>（图片来自阿里云）</p><p><img src="'+c+'" alt="网关与子设备架构图"></p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><h3 id="_1-1-设备类型" tabindex="-1">1.1 设备类型 <a class="header-anchor" href="#_1-1-设备类型" aria-label="Permalink to &quot;1.1 设备类型&quot;">​</a></h3><p>创建产品时，需要选择设备类型。设备类型由 IotProductDeviceTypeEnum 枚举定义，包含以下三种：</p><p><img src="'+r+'" alt="产品设备类型"></p><table tabindex="0"><thead><tr><th>名称</th><th>说明</th></tr></thead><tbody><tr><td>直连设备</td><td>直接连接物联网平台，独立进行数据上报和接收命令</td></tr><tr><td>网关子设备</td><td>不能直接连接物联网平台，需要通过网关设备代理接入</td></tr><tr><td>网关设备</td><td>可以直接连接物联网平台，并且能代理多个子设备接入，管理子设备的拓扑关系</td></tr></tbody></table><p>设备创建时，会自动继承所属产品的设备类型。</p><h3 id="_1-2-网关子设备使用同一套协议" tabindex="-1">1.2 网关子设备使用同一套协议 <a class="header-anchor" href="#_1-2-网关子设备使用同一套协议" aria-label="Permalink to &quot;1.2 网关子设备使用同一套协议&quot;">​</a></h3><p>网关连接物联网平台后，将拓扑关系同步至物联网平台的云端，&quot;代理&quot;子设备进行设备认证、消息上传、指令接收等与物联网平台的通信。</p><p>简单理解</p><p>网关设备就像子设备的&quot;路由器&quot; —— 子设备自身不具备直连物联网平台的能力，需要通过网关进行消息转发和代理通信。</p><p>① <strong>网关子设备与直连设备使用完全相同的协议。</strong> 以 MQTT 协议为例，子设备的属性上报、事件上报、服务调用等，都跟直连设备使用相同的主题和消息格式：</p><table tabindex="0"><thead><tr><th>操作</th><th>直连设备主题</th><th>网关子设备主题</th></tr></thead><tbody><tr><td>属性上报</td><td><code>/sys/{productKey}/{deviceName}/thing/property/post</code></td><td><code>/sys/{productKey}/{deviceName}/thing/property/post</code></td></tr><tr><td>事件上报</td><td><code>/sys/{productKey}/{deviceName}/thing/event/post</code></td><td><code>/sys/{productKey}/{deviceName}/thing/event/post</code></td></tr><tr><td>服务调用</td><td><code>/sys/{productKey}/{deviceName}/thing/service/invoke</code></td><td><code>/sys/{productKey}/{deviceName}/thing/service/invoke</code></td></tr></tbody></table><p>具体来说，子设备不直接连接物联网平台，而是将消息发给网关设备，再由网关设备转发到物联网平台：</p><ul><li><strong>认证</strong>：网关设备使用子设备的三元组（productKey + deviceName + deviceSecret）向平台执行认证</li><li><strong>上报</strong>：网关设备以子设备的 <code>{productKey}/{deviceName}</code> 为主题，将子设备的数据上报到平台</li><li><strong>下发</strong>：平台以子设备的 <code>{productKey}/{deviceName}</code> 为主题下发指令，由网关设备接收后转发给子设备</li></ul><p>② 网关设备<strong>独有</strong>的操作包括：</p><ul><li>拓扑管理：<code>thing.topo.add</code>、<code>thing.topo.delete</code>、<code>thing.topo.get</code>、<code>thing.topo.change</code></li><li>子设备动态注册：<code>thing.auth.register.sub</code>（详见 <a href="./device-register">《设备动态注册》</a>）</li><li>批量上报：<code>thing.event.property.pack.post</code>（网关一次上报自身 + 多个子设备的数据）</li></ul><h3 id="_1-3-拓扑关系的两种管理方式" tabindex="-1">1.3 拓扑关系的两种管理方式 <a class="header-anchor" href="#_1-3-拓扑关系的两种管理方式" aria-label="Permalink to &quot;1.3 拓扑关系的两种管理方式&quot;">​</a></h3><p>拓扑关系（即网关与子设备的绑定关系）支持<strong>两种管理方式</strong>：</p><table tabindex="0"><thead><tr><th>方式</th><th>说明</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>方式一：后台绑定</strong></td><td>管理员在管理后台手动绑定/解绑子设备，操作完成后平台下发 <code>thing.topo.change</code> 通知给网关</td><td>部署阶段、手动配置</td></tr><tr><td><strong>方式二：协议绑定</strong></td><td>网关设备通过 MQTT 协议主动上报 <code>thing.topo.add</code>/<code>delete</code>/<code>get</code> 消息，动态管理拓扑关系</td><td>运行阶段、自动发现</td></tr></tbody></table><p>两种方式可以并存，互不影响。</p><h3 id="_1-4-表结构设计" tabindex="-1">1.4 表结构设计 <a class="header-anchor" href="#_1-4-表结构设计" aria-label="Permalink to &quot;1.4 表结构设计&quot;">​</a></h3><p>在 <code>iot_device</code> 表中，通过 <code>device_type</code> 和 <code>gateway_id</code> 字段支持网关与子设备的关联关系：</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>device_type</code></td><td><code>tinyint</code></td><td>设备类型，参见 IotProductDeviceTypeEnum 枚举</td></tr><tr><td><code>gateway_id</code></td><td><code>bigint</code></td><td>网关设备 ID，子设备需要关联的网关设备 ID（直连/网关设备为空）</td></tr></tbody></table><h2 id="_2-拓扑关系管理-后台绑定" tabindex="-1">2. 拓扑关系管理（后台绑定） <a class="header-anchor" href="#_2-拓扑关系管理-后台绑定" aria-label="Permalink to &quot;2. 拓扑关系管理（后台绑定）&quot;">​</a></h2><p>管理员在管理后台手动管理子设备与网关的绑定关系。由 IotDeviceController 提供接口。</p><p>① 在设备详情页，仅「网关设备」显示【子设备管理】Tab 页签。对应前端项目的 <code>@/views/iot/device/device/detail/DeviceDetailsSubDevice.vue</code>。</p><p><img src="'+i+'" alt="设备详情 - 子设备管理"></p><p>展示当前网关下已绑定的所有子设备，包括设备名称、备注名称、所属产品、设备状态、最后上线时间等信息。</p><p>② 点击【添加子设备】按钮，弹出对话框。支持按产品筛选（仅显示「网关子设备」类型的产品），选中未绑定的子设备后确认绑定。</p><p><img src="'+s+'" alt="绑定子设备"></p><p>支持单个解绑和批量解绑。选中已绑定的子设备，点击【解绑】或【批量解绑】按钮即可解除绑定关系。</p><p>后台绑定或解绑操作完成后，平台会通过 <code>thing.topo.change</code> <strong>下行消息</strong>主动通知网关设备，网关设备可据此更新本地拓扑缓存。</p><h2 id="_3-拓扑关系管理-协议绑定" tabindex="-1">3. 拓扑关系管理（协议绑定） <a class="header-anchor" href="#_3-拓扑关系管理-协议绑定" aria-label="Permalink to &quot;3. 拓扑关系管理（协议绑定）&quot;">​</a></h2><p>网关设备也可以通过 MQTT 协议主动管理拓扑关系，实现运行时动态添加/删除子设备。</p><h3 id="_3-1-mqtt-主题格式" tabindex="-1">3.1 MQTT 主题格式 <a class="header-anchor" href="#_3-1-mqtt-主题格式" aria-label="Permalink to &quot;3.1 MQTT 主题格式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>方向</th><th>消息方法</th><th>MQTT 主题</th></tr></thead><tbody><tr><td>添加拓扑关系</td><td>上行</td><td><code>thing.topo.add</code></td><td><code>/sys/{productKey}/{deviceName}/thing/topo/add</code></td></tr><tr><td>删除拓扑关系</td><td>上行</td><td><code>thing.topo.delete</code></td><td><code>/sys/{productKey}/{deviceName}/thing/topo/delete</code></td></tr><tr><td>获取拓扑关系</td><td>上行</td><td><code>thing.topo.get</code></td><td><code>/sys/{productKey}/{deviceName}/thing/topo/get</code></td></tr><tr><td>拓扑变更通知</td><td>下行</td><td><code>thing.topo.change</code></td><td><code>/sys/{productKey}/{deviceName}/thing/topo/change</code></td></tr></tbody></table><p>其中 <code>{productKey}</code> 和 <code>{deviceName}</code> 为<strong>网关设备</strong>的标识。回复主题在原主题后追加 <code>_reply</code> 后缀。</p><h3 id="_3-2-快速测试" tabindex="-1">3.2 快速测试 <a class="header-anchor" href="#_3-2-快速测试" aria-label="Permalink to &quot;3.2 快速测试&quot;">​</a></h3><p>可以通过以下集成测试类快速体验，具体步骤见各类的注释：</p><table tabindex="0"><thead><tr><th>协议</th><th>网关设备</th><th>网关子设备</th></tr></thead><tbody><tr><td>MQTT</td><td>IotGatewayDeviceMqttProtocolIntegrationTest</td><td>IotGatewaySubDeviceMqttProtocolIntegrationTest</td></tr><tr><td>HTTP</td><td>IotGatewayDeviceHttpProtocolIntegrationTest</td><td>IotGatewaySubDeviceHttpProtocolIntegrationTest</td></tr><tr><td>CoAP</td><td>IotGatewayDeviceCoapProtocolIntegrationTest</td><td>IotGatewaySubDeviceCoapProtocolIntegrationTest</td></tr><tr><td>TCP</td><td>IotGatewayDeviceTcpProtocolIntegrationTest</td><td>IotGatewaySubDeviceTcpProtocolIntegrationTest</td></tr><tr><td>UDP</td><td>IotGatewayDeviceUdpProtocolIntegrationTest</td><td>IotGatewaySubDeviceUdpProtocolIntegrationTest</td></tr><tr><td>WebSocket</td><td>IotGatewayDeviceWebSocketProtocolIntegrationTest</td><td>IotGatewaySubDeviceWebSocketProtocolIntegrationTest</td></tr></tbody></table><h3 id="_3-3-消息数据结构" tabindex="-1">3.3 消息数据结构 <a class="header-anchor" href="#_3-3-消息数据结构" aria-label="Permalink to &quot;3.3 消息数据结构&quot;">​</a></h3><p>拓扑相关的消息数据结构定义在 <code>yudao-module-iot-core</code> 模块的 <code>core.topic.topo</code> 包中：</p><table tabindex="0"><thead><tr><th>消息方法</th><th>方向</th><th>数据结构类</th><th>说明</th></tr></thead><tbody><tr><td><code>thing.topo.add</code></td><td>上行</td><td>IotDeviceTopoAddReqDTO</td><td>包含 <code>subDevices</code> 子设备认证信息列表</td></tr><tr><td><code>thing.topo.delete</code></td><td>上行</td><td>IotDeviceTopoDeleteReqDTO</td><td>包含 <code>subDevices</code> 子设备标识列表</td></tr><tr><td><code>thing.topo.get</code></td><td>上行</td><td>IotDeviceTopoGetReqDTO</td><td>目前为空，预留扩展</td></tr><tr><td><code>thing.topo.get</code></td><td>上行</td><td>IotDeviceTopoGetRespDTO</td><td>包含 <code>subDevices</code> 子设备标识列表</td></tr><tr><td><code>thing.topo.change</code></td><td>下行</td><td>IotDeviceTopoChangeReqDTO</td><td>包含 <code>status</code>（0=创建/1=删除）和 <code>subList</code> 子设备列表</td></tr></tbody></table><h2 id="_4-网关批量上报" tabindex="-1">4. 网关批量上报 <a class="header-anchor" href="#_4-网关批量上报" aria-label="Permalink to &quot;4. 网关批量上报&quot;">​</a></h2><p>网关设备支持<strong>批量上报</strong>功能：一次消息同时上报网关自身和多个子设备的属性、事件数据。这是网关设备独有的操作，对应 <code>thing.event.property.pack.post</code> 消息方法。</p><p>以 MQTT 协议为例，网关设备上报批量消息的主题和数据格式如下：</p><ul><li><p>MQTT 主题：<code>/sys/{gatewayProductKey}/{gatewayDeviceName}/thing/event/property/pack/post</code></p></li><li><p>数据格式：对应 IotDevicePropertyPackPostReqDTO 类</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span></code></pre></div></li></ul><p>{ &quot;method&quot;: &quot;thing.event.property.pack.post&quot;, &quot;params&quot;: { &quot;properties&quot;: { &quot;cpuUsage&quot;: 45.2 }, &quot;events&quot;: { &quot;alert&quot;: { &quot;value&quot;: { &quot;level&quot;: 1 }, &quot;time&quot;: 1739265600000 } }, &quot;subDevices&quot;: [ { &quot;identity&quot;: { &quot;productKey&quot;: &quot;YzvHxd4r67sT4s2B&quot;, &quot;deviceName&quot;: &quot;small&quot; }, &quot;properties&quot;: { &quot;temperature&quot;: 36.5, &quot;humidity&quot;: 60 }, &quot;events&quot;: { &quot;eat&quot;: { &quot;value&quot;: { &quot;rice&quot;: 3 }, &quot;time&quot;: 1739265600000 } } } ] } }</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>\n<span class="line"><span>平台收到后，会将批量消息拆分为各设备独立的 `thing.property.post` 和 `thing.event.post` 消息分别处理。具体可见 IotDeviceMessageServiceImpl 的 `#handlePackMessage(...)` 方法。</span></span></code></pre></div>',55)])])}const y=e(n,[["render",p]]);export{v as __pageData,y as default};
